<?php
namespace App\Models;
use App\Core\Model;
use App\Core\Database;
final class Purchase extends Model {
 public function list():array{return $this->all("SELECT po.*,s.company_name,u.full_name FROM purchase_orders po JOIN suppliers s ON s.id=po.supplier_id JOIN users u ON u.id=po.user_id ORDER BY po.created_at DESC");}
 public function create(int $supplierId,array $items,int $userId,string $notes=''):int{return Database::transaction(function($db)use($supplierId,$items,$userId,$notes){$no='ACH-'.date('Ymd-His');$total=0;foreach($items as $i)$total+=(float)$i['qty']*(float)$i['price'];$db->prepare("INSERT INTO purchase_orders(order_no,supplier_id,status,subtotal,total,ordered_at,user_id,notes) VALUES(?,?,'COMMANDE',?,?,NOW(),?,?)")->execute([$no,$supplierId,$total,$total,$userId,$notes]);$id=(int)$db->lastInsertId();$st=$db->prepare("INSERT INTO purchase_order_items(purchase_order_id,product_id,quantity,unit_price,subtotal) VALUES(?,?,?,?,?)");foreach($items as $i)$st->execute([$id,$i['product_id'],$i['qty'],$i['price'],(float)$i['qty']*(float)$i['price']]);return$id;});}
 public function receive(int $id,int $userId):void{Database::transaction(function($db)use($id,$userId){$st=$db->prepare("SELECT * FROM purchase_orders WHERE id=? FOR UPDATE");$st->execute([$id]);$po=$st->fetch();if(!$po||!in_array($po['status'],['COMMANDE','PARTIELLEMENT_RECU'],true))throw new \RuntimeException('Commande déjà traitée.');$it=$db->prepare("SELECT * FROM purchase_order_items WHERE purchase_order_id=?");$it->execute([$id]);foreach($it->fetchAll() as $row){$remaining=(float)$row['quantity']-(float)$row['received_quantity'];if($remaining<=0)continue;$ss=$db->prepare("SELECT quantity FROM stocks WHERE product_id=? FOR UPDATE");$ss->execute([$row['product_id']]);$before=(float)$ss->fetch()['quantity'];$after=$before+$remaining;$db->prepare("UPDATE stocks SET quantity=? WHERE product_id=?")->execute([$after,$row['product_id']]);$db->prepare("UPDATE purchase_order_items SET received_quantity=quantity WHERE id=?")->execute([$row['id']]);$db->prepare("UPDATE products SET purchase_price=? WHERE id=?")->execute([$row['unit_price'],$row['product_id']]);$db->prepare("INSERT INTO stock_movements(product_id,type,quantity,stock_before,stock_after,user_id,reason,reference_no) VALUES(?,'ENTREE',?,?,?,?,?,?)")->execute([$row['product_id'],$remaining,$before,$after,$userId,'Réception fournisseur',$po['order_no']]);}$db->prepare("UPDATE purchase_orders SET status='RECU',received_at=NOW() WHERE id=?")->execute([$id]);});}
}
